const inputData = $input.first().json || {};
const body = inputData.body || inputData;
const testCases = body.testCases || [];
const baseUrl = (body.baseUrl || process.env.SQUASH_BASE_URL || '').replace(/\/$/, '');
const apiToken = body.apiToken || process.env.SQUASH_API_TOKEN || '';
const folderId = body.folderId || process.env.SQUASH_TC_G31_FOLDER_ID;
const projectId = body.projectId || process.env.SQUASH_PROJECT_ID;

let triggerSource = 'mattermost';
try {
  if ($('Webhook Trigger (squash-batch)').first()) {
    triggerSource = 'webhook';
  }
} catch (e) {
  triggerSource = 'mattermost';
}

// Chuẩn bị danh sách payload động kèm token và URL để gửi song song lên Squash TM
if (testCases.length === 0) {
  return [{
    json: {
      isEmpty: true,
      baseUrl: baseUrl,
      apiToken: apiToken,
      folderId: folderId,
      projectId: projectId,
      _triggerSource: triggerSource
    }
  }];
}

return testCases.map(tc => ({
  json: {
    baseUrl: baseUrl,
    apiToken: apiToken,
    folderId: folderId,
    projectId: projectId,
    name: tc.name || 'Test Case',
    reference: tc.reference || '',
    description: tc.description || '',
    prerequisite: tc.prerequisite || '',
    _triggerSource: triggerSource
  }
}));

const results = $input.all();
const first = results[0] ? results[0].json : {};
const triggerSource = first._triggerSource || 'mattermost';

if (first.isEmpty) {
  return [{
    json: {
      status: 'error',
      isError: true,
      totalImported: 0,
      reportText: '⚠️ **[Squash Batch Pusher]** Không tìm thấy danh sách test cases nào trong payload để đẩy lên Squash TM.',
      _triggerSource: triggerSource
    }
  }];
}

const errors = [];
const createdCases = [];

for (const r of results) {
  const j = r.json || {};
  if (j.error || (j.status && j.status >= 400)) {
    errors.push((j.error && (j.error.message || j.error.description)) || j.message || 'Lỗi HTTP ' + j.status);
  } else if (j.id) {
    createdCases.push({ id: j.id, name: j.name || '' });
  }
}

const isError = errors.length > 0;
let reportText = '';
if (isError && createdCases.length === 0) {
  reportText = `🚨 **[Lỗi Đẩy Test Case Squash TM]** Không thể tạo test case nào lên hệ thống:\n> ${errors[0]}\n\n*Gợi ý: Hãy kiểm tra SQUASH_BASE_URL, SQUASH_API_TOKEN và folderId trong .env.*`;
} else if (isError && createdCases.length > 0) {
  reportText = `⚠️ **[Cảnh Báo Squash TM]** Đã tạo thành công **${createdCases.length}** test cases, nhưng có **${errors.length}** test cases thất bại.\n> Lỗi mẫu: ${errors[0]}`;
} else {
  reportText = `### 🧪 Batch Push Squash TM Hoàn Tất\n- **Tổng số test case đã tạo:** ${createdCases.length}\n- **Trạng thái:** ✅ Thành công 100%`;
}

return [{
  json: {
    status: isError ? (createdCases.length > 0 ? 'partial' : 'failed') : 'success',
    isError: isError,
    totalImported: createdCases.length,
    failedCount: errors.length,
    createdCases: createdCases,
    errors: errors,
    reportText: reportText,
    _triggerSource: triggerSource
  }
}];
